head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf32202";
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_O_INITDATE", fn: function(){ return (!(String(((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })())) == null ? '' : ((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_126", fn: function(){ return (!(String(((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })())) == null ? '' : ((dma_Cal4.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal4.O_INITDATE"); })()))).length === 0)); } }, { id: "if_O_INITDATE_2", fn: function(){ return (!(String(((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })())) == null ? '' : ((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_244", fn: function(){ return (!(String(((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })())) == null ? '' : ((dma_Cal5.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal5.O_INITDATE"); })()))).length === 0)); } }, { id: "if_O_INITDATE_3", fn: function(){ return (!(String(((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })())) == null ? '' : ((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_422", fn: function(){ return (!(String(((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })())) == null ? '' : ((dma_Cal7.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal7.O_INITDATE"); })()))).length === 0)); } }, { id: "if_O_INITDATE_4", fn: function(){ return (!(String(((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })())) == null ? '' : ((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_523", fn: function(){ return (!(String(((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })())) == null ? '' : ((dma_Cal8.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal8.O_INITDATE"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "ㆍ기산일 : " + String(dma_Cal4.get("O_INITDATE")); } },
        { childId: "__rb1", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal7.get("O_INITDATE")); } },
        { childId: "__rb2", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal8.get("O_INITDATE")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", COM_NM);
};

// [A] 초기 목록 미해결 — jldstf32202: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf32202' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf32202' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf32202.onpageload' });
    }
};

