/**
 * @method
 * @name cal3
 * @description cal3 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal3 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    if (frmCal3.bod_resol_dd.value === "") {
        await $c.win.alert("[이사회결의일  ]을 입력하세요.");
        bod_resol_dd.focus();
        return;
    }
    if (frmCal3.new_isu_shrs.value === "") {
        await $c.win.alert("[신발행주식수 ]을 입력하세요.");
        new_isu_shrs.focus();
        return;
    }
    if (frmCal3.old_isu_shrs.value === "") {
        await $c.win.alert("[기발행주식수   ]을 입력하세요.");
        old_isu_shrs.focus();
        return;
    }
    if (frmCal3.dc_rate.value === "") {
        await $c.win.alert("[할인율  ]을 입력하세요.");
        dc_rate.focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal4Req').set('method', "processCalculateRelatedDisclosure3");
    frmCal3.submit();
};

/**
 * @method
 * @name cal4
 * @description cal4 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal4 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    if (($c.util.getComponent('cal_allotStockBeforeThreeDay').getValue() == null ? '' : String($c.util.getComponent('cal_allotStockBeforeThreeDay').getValue())) === '') {
        await $c.win.alert("[신주배정기준일전 3거래일 ]을 입력하세요.");
        $c.util.getComponent("cal_allotStockBeforeThreeDay").focus();
        return;
    }
    if (($c.util.getComponent('ipt_newStockAmountForFirst').getValue() == null ? '' : String($c.util.getComponent('ipt_newStockAmountForFirst').getValue())) === '') {
        await $c.win.alert("[신발행주식수 ]을 입력하세요.");
        $c.util.getComponent("ipt_newStockAmountForFirst").focus();
        return;
    }
    if (($c.util.getComponent('ipt_oldStockAmountForFirst').getValue() == null ? '' : String($c.util.getComponent('ipt_oldStockAmountForFirst').getValue())) === '') {
        await $c.win.alert("[발행주식수  ]을 입력하세요.");
        $c.util.getComponent("ipt_oldStockAmountForFirst").focus();
        return;
    }
    if (($c.util.getComponent('ipt_discountRateForFirst').getValue() == null ? '' : String($c.util.getComponent('ipt_discountRateForFirst').getValue())) === '') {
